  cohort_high_conf_b: number; // $ of HIGH+MED tier loans (whole cohort)
  cohort_low_tier_b: number;  // $ of LOW tier loans (estimated OR drifting disclosed dates)
  cohort_estimated_b: number; // $ of loans dated by an estimate
