  pct_ever_na: number | null;
  pct_ever_default: number | null;
  pct_ever_default_hc: number | null;
  pct_ever_default_1l: number | null;
  pct_ever_modified: number | null;
  pct_ever_modified_hc: number | null;
  pct_ever_b80: number | null;
  pct_b90_alive: number | null;
  b90_mark_coverage_pct: number | null;
  pct_na_unknown: number;     // % of eligible cost left out: latest NA status unknown
  pct_na_history_gap: number; // % counted as clear but with an earlier unknown quarter
  pct_not_yet_seen: number;   // % of eligible cost its holder had not shown yet (in no base)
  na_partial: boolean;
  hc_cost_share: number;      // % of counted cost with a HIGH or MED date
  pct_mod_unknown: number;    // % of eligible cost shown but with a modification history not judged
  mod_partial: boolean;       // pct_mod_unknown >= 5
  n_loans_1l: number;
  cohort_1l_b: number;
  n_src_disclosed: number;    // holder's own disclosed acq date
  n_src_corrected: number;    // corrected: an own date replaced (peer consensus / first-obs)
  n_src_borrowed: number;     // same tranche at a peer BDC
  n_src_first_seen: number;   // the quarter this BDC first showed the loan
  n_src_name_matched: number; // nearby tranche / long-tail name match / sibling facility
